-- Read-only invariant checks. Each subquery returns the number of violations.
-- 碳积分核对先乘十进制系数再除以 1000，与发放过程保持一致。
SELECT '停车区占用及预留不超容' AS name, (SELECT COUNT(*) FROM v_zone_inventory WHERE occupied+reserved>capacity OR available>occupied) AS errors
UNION ALL SELECT '骑行订单与车辆状态一一对应' AS name, (SELECT COUNT(*) FROM bikes b WHERE (b.status='RIDING')<>(EXISTS(SELECT 1 FROM ride_orders r WHERE r.bike_id=b.id AND r.status='RUNNING')) OR (b.status='RIDING' AND b.current_zone_id IS NOT NULL)) AS errors
UNION ALL SELECT '可借车辆都有停车区且没有开放维修单' AS name, (SELECT COUNT(*) FROM bikes b WHERE status='AVAILABLE' AND (current_zone_id IS NULL OR EXISTS(SELECT 1 FROM maintenance_tickets t WHERE t.bike_id=b.id AND t.status<>'COMPLETED'))) AS errors
UNION ALL SELECT '成功支付与订单状态金额一致' AS name, (SELECT COUNT(*) FROM ride_orders r LEFT JOIN payments p ON p.order_id=r.id WHERE (r.status='PAID')<>(p.id IS NOT NULL) OR (p.id IS NOT NULL AND p.amount_cents<>r.amount_cents)) AS errors
UNION ALL SELECT '有效已支付订单恰有一条版本化积分发放' AS name, (SELECT COUNT(*) FROM ride_orders r LEFT JOIN (SELECT order_id,COUNT(*) awards,MAX(distance_m) distance_m,MAX(points_change) points,MAX(carbon_kg_change) carbon,MAX(factor_kg_per_km) factor,MAX(points_per_km) rate FROM carbon_transactions WHERE entry_type='AWARD' GROUP BY order_id) c ON c.order_id=r.id WHERE (r.status='PAID' AND r.qualification_status='VALID' AND COALESCE(c.awards,0)<>1) OR (r.qualification_status='UNDER_REVIEW' AND COALESCE(c.awards,0)>0) OR (r.qualification_status='EXCLUDED' AND c.awards=1 AND NOT EXISTS(SELECT 1 FROM carbon_transactions reversal WHERE reversal.order_id=r.id AND reversal.entry_type='ADJUSTMENT' AND reversal.idempotency_key IN (CONCAT('exclude-',r.id),CONCAT('auto:exclude-',r.id)) AND reversal.points_change=-c.points AND reversal.carbon_kg_change=-c.carbon)) OR (c.awards=1 AND (c.distance_m<>r.distance_m OR c.carbon<>ROUND(r.distance_m*c.factor/1000,4) OR (c.rate IS NOT NULL AND c.points<>FLOOR(r.distance_m*c.rate/1000))))) AS errors
UNION ALL SELECT '积分流水幂等键唯一且发放关联支付' AS name, (SELECT COUNT(*) FROM carbon_transactions c LEFT JOIN payments p ON p.order_id=c.order_id WHERE c.entry_type='AWARD' AND p.id IS NULL) AS errors
UNION ALL SELECT '归还证据坐标成对且终态复核信息完整' AS name, (SELECT (SELECT COUNT(*) FROM ride_orders WHERE (return_x IS NULL)<>(return_y IS NULL))+(SELECT COUNT(*) FROM return_attempts WHERE (review_status='PENDING' AND (reviewer_id IS NOT NULL OR reviewed_at IS NOT NULL)) OR (review_status<>'PENDING' AND (reviewer_id IS NULL OR reviewed_at IS NULL OR review_note IS NULL)))) AS errors
UNION ALL SELECT '确认的调度建议唯一关联正式任务' AS name, (SELECT COUNT(*) FROM dispatch_suggestions WHERE (status='CONFIRMED' AND task_id IS NULL) OR (status<>'CONFIRMED' AND task_id IS NOT NULL))+(SELECT COUNT(*) FROM (SELECT task_id FROM dispatch_suggestions WHERE task_id IS NOT NULL GROUP BY task_id HAVING COUNT(*)>1) duplicated_tasks)+(SELECT COUNT(*) FROM dispatch_suggestions s LEFT JOIN dispatch_tasks t ON t.id=s.task_id WHERE s.status='CONFIRMED' AND s.task_id IS NOT NULL AND (t.id IS NULL OR s.source_zone_id<>t.source_zone_id OR s.target_zone_id<>t.target_zone_id OR s.quantity<>(SELECT COUNT(*) FROM dispatch_bikes d WHERE d.task_id=s.task_id))) AS errors
UNION ALL SELECT '开放风险指纹无重复' AS name, (SELECT COUNT(*) FROM (SELECT fingerprint FROM risk_alerts WHERE status IN('OPEN','ACKNOWLEDGED') GROUP BY fingerprint HAVING COUNT(*)>1) x) AS errors
UNION ALL SELECT '道路模拟属性在声明范围内' AS name, (SELECT COUNT(*) FROM road_edges WHERE slope_percent NOT BETWEEN -30 AND 30 OR shade_level NOT BETWEEN 0 AND 5 OR lighting_level NOT BETWEEN 0 AND 5 OR intersection_risk NOT BETWEEN 0 AND 5) AS errors
UNION ALL SELECT '调度车辆只属于一个未完成任务' AS name, (SELECT COUNT(*) FROM (SELECT d.bike_id FROM dispatch_bikes d JOIN dispatch_tasks t ON t.id=d.task_id WHERE t.status IN ('PENDING','IN_PROGRESS') GROUP BY d.bike_id HAVING COUNT(*)>1) x) AS errors
UNION ALL SELECT '调度状态与车辆位置一致' AS name, (SELECT COUNT(*) FROM dispatch_tasks t JOIN dispatch_bikes d ON d.task_id=t.id JOIN bikes b ON b.id=d.bike_id WHERE t.status IN ('PENDING','IN_PROGRESS') AND (b.status<>'DISPATCHING' OR (t.status='PENDING' AND NOT(b.current_zone_id<=>t.source_zone_id)) OR (t.status='IN_PROGRESS' AND b.current_zone_id IS NOT NULL))) AS errors
UNION ALL SELECT '调度中车辆有对应活动任务' AS name, (SELECT COUNT(*) FROM bikes b WHERE b.status='DISPATCHING' AND NOT EXISTS(SELECT 1 FROM dispatch_bikes d JOIN dispatch_tasks t ON t.id=d.task_id WHERE d.bike_id=b.id AND t.status IN ('PENDING','IN_PROGRESS'))) AS errors
UNION ALL SELECT '维修状态与开放工单相符' AS name, (SELECT COUNT(*) FROM bikes b WHERE (b.status='MAINTENANCE' AND NOT EXISTS(SELECT 1 FROM maintenance_tickets t WHERE t.bike_id=b.id AND t.status<>'COMPLETED')) OR (EXISTS(SELECT 1 FROM maintenance_tickets t WHERE t.bike_id=b.id AND t.status<>'COMPLETED') AND b.status NOT IN ('MAINTENANCE','RIDING'))) AS errors
UNION ALL SELECT '所有调度任务有车辆明细' AS name, (SELECT COUNT(*) FROM dispatch_tasks t WHERE NOT EXISTS(SELECT 1 FROM dispatch_bikes d WHERE d.task_id=t.id)) AS errors;
